def transform(grid):
    # Find all non-zero positions
    positions = []
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] != 0:
                positions.append((r, c))

    if not positions:
        return grid

    # Calculate bounding box
    min_r, max_r = min(p[0] for p in positions), max(p[0] for p in positions)
    min_c, max_c = min(p[1] for p in positions), max(p[1] for p in positions)

    # Create result grid as copy
    result = [row[:] for row in grid]

    # Draw bounding box edges with 3s
    # Top edge: row min_r, cols min_c to max_c
    for c in range(min_c, max_c + 1):
        if min_r >= len(result) or min_c < 0 or max_c >= len(result[0]):
            continue
        if result[min_r][c] == 0:
            result[min_r][c] = 3

    # Bottom edge: row max_r, cols min_c to max_c
    for c in range(min_c, max_c + 1):
        if result[max_r][c] == 0:
            result[max_r][c] = 3

    # Left edge: col min_c, rows min_r to max_r
    for r in range(min_r, max_r + 1):
        if result[r][min_c] == 0:
            result[r][min_c] = 3

    # Right edge: col max_c, rows min_r to max_r
    for r in range(min_r, max_r + 1):
        if result[r][max_c] == 0:
            result[r][max_c] = 3

    return result

